<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\{BelongsTo,HasMany};
class Sale extends Model { protected $fillable=['invoice_number','sale_date','customer_id','customer_name','payment_type','payment_method','farm_account','subtotal','discount','total','amount_paid','balance','status','approval_status','is_staff_consumption','consumed_by','notes','sold_by']; protected function casts():array{return ['sale_date'=>'date','subtotal'=>'decimal:2','discount'=>'decimal:2','total'=>'decimal:2','amount_paid'=>'decimal:2','balance'=>'decimal:2','is_staff_consumption'=>'boolean'];} public function customer():BelongsTo{return $this->belongsTo(SalesCustomer::class,'customer_id');} public function seller():BelongsTo{return $this->belongsTo(User::class,'sold_by');} public function lines():HasMany{return $this->hasMany(SaleLine::class);} public function payments():HasMany{return $this->hasMany(SalesPayment::class);} public function approvals(){return $this->morphMany(Approval::class,'approvable');} }
